// Reparte la posición de la respuesta correcta (A–D) rotando opciones y explicaciones juntas.
let k = 0, m = 0;
for (const q of Q) {
  if (!['single', 'multi'].includes(q.type)) continue;
  const shift = q.correct.length === 1 ? ([1, 3, 0, 2][k++ % 4] - q.correct[0] + 4) % 4 : [1, 0][m++ % 2];
  const rot = a => a.map((_, i) => a[(i - shift + 4) % 4]);
  q.options = rot(q.options); if (q.why) q.why = rot(q.why);
  q.correct = q.correct.map(c => (c + shift) % 4).sort((a, b) => a - b);
}
// En emparejamiento y listas desplegables, baraja de forma fija las opciones para que la respuesta no sea siempre la primera.
const perm = (n, seed) => { const p = [...Array(n).keys()]; let s = seed; for (let i = n - 1; i > 0; i--) { s = (s * 9301 + 49297) % 233280; const j = s % (i + 1); [p[i], p[j]] = [p[j], p[i]]; } return p; };
Q.forEach((q, qi) => {
  if (q.type === 'match') { const p = perm(q.options.length, 23 + qi), inv = p.map((_, i) => p.indexOf(i)); q.options = p.map(i => q.options[i]); q.correct = q.correct.map(c => inv[c]); }
  if (q.type === 'dropdown') q.choices = q.choices.map((ch, ci) => { const p = perm(ch.length, 41 + qi * 7 + ci), inv = p.map((_, i) => p.indexOf(i)); q.correct[ci] = inv[q.correct[ci]]; return p.map(i => ch[i]); });
});
